-- BroBeasiswa. Impor SEKALI pada database baru melalui phpMyAdmin.
-- Tidak menggunakan DROP agar impor ulang tidak menghapus data yang sudah ada.
CREATE DATABASE IF NOT EXISTS infokesempatan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE infokesempatan;
SET NAMES utf8mb4;
SET time_zone = '+07:00';

CREATE TABLE pengguna (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(30) NOT NULL UNIQUE,
    nama VARCHAR(100) NOT NULL,
    peran ENUM('admin', 'anggota') NOT NULL DEFAULT 'anggota',
    hash_sandi VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE informasi (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    pengguna_id INT UNSIGNED NOT NULL,
    judul VARCHAR(150) NOT NULL,
    jenis ENUM('beasiswa', 'lomba') NOT NULL,
    penyelenggara VARCHAR(150) NOT NULL,
    deadline DATE NOT NULL,
    persyaratan TEXT NOT NULL,
    deskripsi TEXT NOT NULL,
    url_pendaftaran VARCHAR(2000) NOT NULL,
    pendanaan ENUM('Penuh', 'Sebagian') NULL,
    biaya INT UNSIGNED NULL,
    peserta ENUM('Individu', 'Tim') NULL,
    sumber_url VARCHAR(512) NULL UNIQUE,
    diambil_pada DATETIME NULL,
    mulai DATE NULL,
    lokasi VARCHAR(500) NULL,
    jenjang VARCHAR(500) NULL,
    poster_url VARCHAR(2000) NULL,
    dibuat_pada DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (pengguna_id) REFERENCES pengguna(id),
    INDEX idx_terbaru (dibuat_pada, id),
    INDEX idx_deadline (deadline),
    CONSTRAINT kolom_sesuai_jenis CHECK (
        (jenis = 'beasiswa' AND biaya IS NULL AND peserta IS NULL)
        OR (jenis = 'lomba' AND pendanaan IS NULL AND (biaya IS NULL OR biaya BETWEEN 0 AND 100000000))
    )
) ENGINE=InnoDB;

