-- Seluruh nama penyelenggara, program, dan URL berikut adalah SIMULASI.
-- Deadline relatif ke hari impor, agar contoh tetap dapat dipakai di semester lain.
INSERT INTO informasi (pengguna_id, judul, jenis, penyelenggara, deadline, persyaratan, deskripsi, url_pendaftaran, pendanaan, biaya, peserta, dibuat_pada) VALUES
(1, 'Beasiswa Prestasi Nusantara', 'beasiswa', 'Yayasan Cakrawala Pendidikan (Simulasi)', DATE_ADD(CURDATE(), INTERVAL 45 DAY), 'Mahasiswa aktif S1 semester 2–6.\nIPK minimal 3,50.\nSiapkan transkrip nilai dan esai rencana studi.', 'Data simulasi untuk praktikum. Dukungan biaya kuliah penuh bagi mahasiswa yang ingin mengembangkan prestasi akademik dan kontribusi sosial.', 'https://example.com/beasiswa-prestasi', 'Penuh', NULL, NULL, DATE_SUB(NOW(), INTERVAL 5 DAY)),
(1, 'Beasiswa Penggerak Komunitas', 'beasiswa', 'Komunitas Tumbuh Bersama (Simulasi)', DATE_ADD(CURDATE(), INTERVAL 30 DAY), 'Mahasiswa aktif semua jurusan.\nMemiliki pengalaman kegiatan sosial.\nLampirkan portofolio kegiatan dan surat rekomendasi.', 'Data simulasi untuk praktikum. Pendanaan sebagian untuk mahasiswa yang aktif menggerakkan kegiatan sosial di lingkungan sekitarnya.', 'https://example.com/beasiswa-komunitas', 'Sebagian', NULL, NULL, DATE_SUB(NOW(), INTERVAL 4 DAY)),
(1, 'Beasiswa Talenta Digital', 'beasiswa', 'Institut Inovasi Digital (Simulasi)', DATE_ADD(CURDATE(), INTERVAL 60 DAY), 'Mahasiswa aktif bidang teknologi.\nMemiliki satu proyek atau portofolio digital.\nBersedia mengikuti sesi pendampingan.', 'Data simulasi untuk praktikum. Kesempatan pendanaan penuh dan pendampingan bagi mahasiswa yang sedang membangun karya di bidang teknologi.', 'https://example.com/beasiswa-digital', 'Penuh', NULL, NULL, DATE_SUB(NOW(), INTERVAL 3 DAY)),
(1, 'Kompetisi Desain Solusi Kampus', 'lomba', 'Forum Kreatif Mahasiswa (Simulasi)', DATE_ADD(CURDATE(), INTERVAL 21 DAY), 'Tim mahasiswa aktif.\nKarya orisinal yang menjawab masalah kampus.\nSiapkan proposal singkat dan prototipe.', 'Data simulasi untuk praktikum. Tantangan merancang solusi yang membuat kehidupan kampus lebih nyaman melalui desain dan teknologi.', 'https://example.com/lomba-desain', NULL, 25000, 'Tim', DATE_SUB(NOW(), INTERVAL 2 DAY)),
(1, 'Lomba Esai Masa Depan Pendidikan', 'lomba', 'Ruang Gagasan Nusantara (Simulasi)', DATE_ADD(CURDATE(), INTERVAL 14 DAY), 'Mahasiswa aktif seluruh Indonesia.\nEsai berbahasa Indonesia sepanjang 1.000–1.500 kata.\nKarya belum pernah dipublikasikan.', 'Data simulasi untuk praktikum. Tuangkan gagasan tentang pendidikan yang lebih inklusif melalui esai dengan argumentasi dan sumber yang jelas.', 'https://example.com/lomba-esai', NULL, 0, 'Individu', DATE_SUB(NOW(), INTERVAL 1 DAY));

